"""
意图分类器 - 基于中文语义嵌入

核心原理：
1. 使用 BAAI/bge-base-zh-v1.5 将输入转为向量
2. 与预定义的各类意图例句向量做余弦相似度对比
3. 取最匹配的意图返回
4. LRU 缓存 + 关键词回退保证可靠性
"""

import os
import sys
import pickle
from typing import Dict, List, Optional, Tuple, Set
from collections import OrderedDict
import numpy as np

# ★★★ sklearn MLP 分类头（懒加载，不阻塞启动）★★★
_HAS_SKLEARN: Optional[bool] = None

def _check_sklearn_available():
    """懒检测 sklearn 是否可用（避免模块导入时加载 numpy/scipy）"""
    global _HAS_SKLEARN
    if _HAS_SKLEARN is None:
        try:
            import sklearn.neural_network  # noqa: F401
            import sklearn.preprocessing   # noqa: F401
            _HAS_SKLEARN = True
        except ImportError:
            _HAS_SKLEARN = False
    return _HAS_SKLEARN

# ★★★ MLP 模型持久化路径 ★★★
_MLP_MODEL_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "user_features", "intent_mlp_model")

# ★★★ 预计算 embeddings 持久化路径 ★★★
_EMBEDDINGS_PATH = os.path.join(_MLP_MODEL_DIR, "intent_embeddings.npz")


# ==================== 镜像配置（下载模型用） ====================

os.environ["HF_ENDPOINT"] = "https://hf-mirror.com"


