# ★★★ 合并错别字变体数据（由 generate_typo_data.py 生成）★★★
try:
    from .intent_examples_typo import INTENT_EXAMPLES_TYPO
    for _intent, _examples in INTENT_EXAMPLES_TYPO.items():
        if _intent in INTENT_EXAMPLES:
            # 去重：避免原文已存在的句子被重复加入
            _existing = set(INTENT_EXAMPLES[_intent])
            _new = [s for s in _examples if s not in _existing]
            INTENT_EXAMPLES[_intent].extend(_new)
        else:
            INTENT_EXAMPLES[_intent] = list(_examples)
    print(f"  ✅ 已合并错别字变体数据（共 {sum(len(v) for v in INTENT_EXAMPLES_TYPO.values())} 条）")
except (ImportError, FileNotFoundError):
    pass  # 无错别字数据文件时正常使用原始数据

# ★★★ 合并 LLM 扩充例句（由 generate_intent_examples.py 生成）★★★
try:
    from .intent_examples_llm import INTENT_EXAMPLES_LLM
    for _intent, _examples in INTENT_EXAMPLES_LLM.items():
        if _intent in INTENT_EXAMPLES:
            _existing = set(INTENT_EXAMPLES[_intent])
            _new = [s for s in _examples if s not in _existing]
            INTENT_EXAMPLES[_intent].extend(_new)
        else:
            INTENT_EXAMPLES[_intent] = list(_examples)
    print(f"  ✅ 已合并 LLM 扩充例句（共 {sum(len(v) for v in INTENT_EXAMPLES_LLM.values())} 条）")
except (ImportError, FileNotFoundError):
    pass  # 无 LLM 扩充数据时正常使用原始数据

