# 独有关键词：只出现在一个意图关键词列表中的词，匹配时可高置信度覆盖模型结果
_EXCLUSIVE_KEYWORDS: Dict[str, List[str]] = {}
_word_to_intents: Dict[str, List[str]] = {}
for _intent, _keywords in FALLBACK_KEYWORDS.items():
    for _kw in _keywords:
        _word_to_intents.setdefault(_kw, []).append(_intent)
for _kw, _intents in _word_to_intents.items():
    if len(_intents) == 1:
        _EXCLUSIVE_KEYWORDS.setdefault(_intents[0], []).append(_kw)

