class IntentClassifier:
    """
    基于中文语义嵌入的意图分类器

    使用 BAAI/bge-base-zh-v1.5 计算文本向量，通过余弦相似度
    匹配最接近的意图类别。内置 LRU 缓存和关键词回退。
    """

    def __init__(self):
        self._model = None
        self._intent_embeddings: Optional[Dict[str, np.ndarray]] = None
        self._mlp = None
        self._label_encoder = None
        self._fallback_keywords = FALLBACK_KEYWORDS
        self._cache: OrderedDict = OrderedDict()
        self._cache_size = 128
        # ★★★ P0-1: 精确例句匹配快速路径（绕过模型）★★★
        # 归一化文本 → intent，O(1) 查表，避免模型对训练集已知句子的误判
        self._exact_match_map: Dict[str, str] = {}
        self._build_exact_match_map()

    @staticmethod
    def _normalize_text(text: str) -> str:
        """归一化文本用于精确匹配：去空白/标点 + 转小写"""
        import re
        return re.sub(r"[\s，。！？,.!?]", "", text).lower()

    def _build_exact_match_map(self) -> None:
        """构建归一化例句 → 意图 的查表字典。
        若同一归一化句子出现在多个意图下，保留首次出现的（与训练清洗逻辑一致）。"""
        seen: Dict[str, str] = {}
        for intent, examples in INTENT_EXAMPLES.items():
            for ex in examples:
                key = self._normalize_text(ex)
                if key not in seen:
                    seen[key] = intent
        self._exact_match_map = seen

    def _load_model(self):
        # ★★★ 国内网络环境下使用 Hugging Face 镜像 ★★★
        import os
        if "HF_ENDPOINT" not in os.environ:
            os.environ["HF_ENDPOINT"] = "https://hf-mirror.com"

        from sentence_transformers import SentenceTransformer
        _MODEL_NAME = "BAAI/bge-base-zh-v1.5"
        print(f"  ⏳ 正在加载语义嵌入模型 {_MODEL_NAME}...")

        # 尝试 1：本地缓存
        try:
            self._model = SentenceTransformer(_MODEL_NAME, local_files_only=True)
            print("  ✅ 从本地缓存加载成功")
        except Exception:
            self._model = None

        # 尝试 2：ModelScope（国内稳定）
        if self._model is None:
            try:
                from modelscope import snapshot_download
                print("  ⏳ 尝试从 ModelScope 下载...")
                _project_root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
                local_path = snapshot_download(_MODEL_NAME, cache_dir=os.path.join(_project_root, ".cache_models"))
                self._model = SentenceTransformer(local_path)
                print("  ✅ 从 ModelScope 下载成功")
            except ImportError:
                print("  ℹ️  modelscope 未安装，跳过")
            except Exception as e:
                print(f"  ⚠️  ModelScope 下载失败: {e}")

        # 尝试 3：HuggingFace 镜像
        if self._model is None:
            try:
                print(f"  ⏳ 尝试从 hf-mirror.com 下载...")
                self._model = SentenceTransformer(_MODEL_NAME)
                print("  ✅ 从 HuggingFace 镜像下载成功")
            except Exception as e:
                print(f"  ❌ 所有下载源均失败: {e}")
                raise RuntimeError(f"无法下载 {_MODEL_NAME} 模型，请检查网络或手动下载")

        # ★★★ 优先从磁盘加载预计算 embeddings（秒级），不存在则实时计算 ★★★
        if not self._load_precomputed_embeddings():
            print("  ⏳ 未找到预计算 embeddings，正在实时编码所有意图例句（约需 1-2 分钟）...")
            self._precompute_embeddings()
            self._save_precomputed_embeddings()
        # ★★★ _load_mlp_model 内部懒检测 sklearn 是否可用，不阻塞 ★★★
        self._load_mlp_model()

    def _precompute_embeddings(self):
        self._intent_embeddings = {}
        for intent, examples in INTENT_EXAMPLES.items():
            embs = self._model.encode(examples, normalize_embeddings=True)
            self._intent_embeddings[intent] = embs

    def _load_precomputed_embeddings(self) -> bool:
        """从磁盘加载预计算 embeddings，成功返回 True"""
        try:
            if not os.path.exists(_EMBEDDINGS_PATH):
                return False
            data = np.load(_EMBEDDINGS_PATH, allow_pickle=True)
            self._intent_embeddings = {}
            for key in data.keys():
                self._intent_embeddings[key] = data[key]
            data.close()
            print(f"  ✅ 已从磁盘加载预计算 embeddings（{len(self._intent_embeddings)} 个意图）")
            return True
        except Exception as e:
            print(f"  ⚠️ 加载预计算 embeddings 失败: {e}")
            return False

    def _save_precomputed_embeddings(self):
        """将预计算 embeddings 保存到磁盘"""
        try:
            os.makedirs(_MLP_MODEL_DIR, exist_ok=True)
            save_dict = {}
            for intent, embs in self._intent_embeddings.items():
                save_dict[intent] = embs
            np.savez_compressed(_EMBEDDINGS_PATH, **save_dict)
            print(f"  💾 预计算 embeddings 已保存: {_EMBEDDINGS_PATH}")
        except Exception as e:
            print(f"  ⚠️ 保存预计算 embeddings 失败: {e}")

    # ==================== LLM 回退：置信度门控的加权集成 ====================

    def _multi_agent_llm_fallback(self, text: str) -> Optional[Tuple[str, float]]:
        """
        多Agent辩论式LLM回退。

        在一个LLM调用中模拟3个不同视角的"审核员"，各自投票，
        通过多数决产出最终意图。比单次LLM调用更鲁棒，延迟几乎不变。
        """
        try:
            from utils.llm_config import get_chat_openai
            llm = get_chat_openai(temperature=0.0, max_tokens=200, timeout=30)

            _intent_desc = {
                "practice": "编程练习题/算法实现——用户要写代码编程",
                "judge_code": "代码调试/查错——用户代码出错了需要排查",
                "question_gen": "理论题/选择题/判断题——用户要出卷子或概念考题",
                "doc_gen": "生成文档/笔记/总结",
                "extension": "拓展阅读/深入原理",
                "video": "找视频/看教程",
                "mindmap": "思维导图",
                "animation": "动画/可视化演示",
                "ppt": "PPT/幻灯片/演示文稿",
                "study_plan": "学习计划/学习路线",
                "chat": "闲聊/问候/非学习类对话",
                "register": "注册/填写个人信息",
                "refine_ppt": "优化PPT",
                "teacher_advice": "询问老师建议",
                "profile_modify": "修改个人信息",
            }
            intent_options = "\n".join([f"  - {k}: {_intent_desc.get(k, '')}" for k in INTENT_EXAMPLES.keys()])

            prompt = f"""你是三个意图分类专家，请从各自角度分析用户输入并投票。

--- 专家1（严谨派）---
你的原则：严格按照语义分类。'帮我'、'请'、'我想'等只是礼貌用语，不改变核心意图。
用户说"帮我做PPT"的核心意图是PPT，不是闲聊。只有当输入确实是纯粹问候/告别/感谢时，
才投chat。

--- 专家2（语义派）---
你的原则：关注用户实际想做什么，而非表达方式。忽略所有请求格式前缀
（帮我、请、我想、能不能、需要），提取真实的动作意图。
例如"帮我查一下XXX"核心是"查询信息"→chat；"帮我做一个PPT"核心是"做PPT"→ppt。

--- 专家3（细节派）---
你的原则：逐词分析。查找输入中最具体的动作词和主题词。
有具体文档/PPT/视频/学习相关主题词时，优先匹配具体意图。

可用意图列表：
{intent_options}

用户输入：{text}

请按以下格式输出三位的投票（只输出意图名称，一行一个）：
专家1: <意图>
专家2: <意图>
专家3: <意图>"""

            response = llm.invoke(prompt)
            result = response.content.strip()

            # 解析三票
            votes = {}
            for line in result.split("\n"):
                line = line.strip()
                if ":" not in line:
                    continue
                _, _, vote_raw = line.partition(":")
                vote = vote_raw.strip().lower()
                # 匹配到正确的意图名称
                matched_intent = None
                for label in INTENT_EXAMPLES:
                    if label in vote or vote in label:
                        matched_intent = label
                        break
                if matched_intent:
                    votes[matched_intent] = votes.get(matched_intent, 0) + 1

            if not votes:
                return None

            # 多数决
            sorted_votes = sorted(votes.items(), key=lambda x: x[1], reverse=True)
            winner = sorted_votes[0][0]
            vote_count = sorted_votes[0][1]
            total_agents = 3

            # ★★★ chat保护：如果只有1票是chat，其他两票是具体意图，拒绝chat ★★★
            if winner == "chat" and vote_count <= 1 and len(votes) >= 2:
                # 找非chat的最高票
                non_chat = [(i, c) for i, c in sorted_votes if i != "chat"]
                if non_chat and non_chat[0][1] >= vote_count:
                    winner = non_chat[0][0]
                    vote_count = non_chat[0][1]
                    print(f"  🤝 [多Agent辩论] chat被多数否决，采用: {winner}({vote_count}/{total_agents})")

            # 置信度 = 共识度映射
            confidence = 0.5 + (vote_count / total_agents) * 0.35
            print(f"  🤝 [多Agent辩论] 投票: {dict(votes)} → {winner}({confidence:.2f})")
            return winner, min(confidence, 0.85)

        except Exception as e:
            print(f"  ⚠️ 多Agent辩论回退失败: {e}")
            return None

    # ★★★ 保留单LLM回退作为多Agent的降级 ★★★
    def _llm_fallback(self, text: str) -> Optional[Tuple[str, float]]:
        """
        使用单LLM作为第二意见（降级方案）。
        仅在多Agent辩论失败时使用。
        """
        try:
            from utils.llm_config import get_chat_openai
            llm = get_chat_openai(temperature=0.0, max_tokens=50, timeout=30)

            prompt = f"""你是一个专业的意图分类专家。请根据用户输入判断最匹配的意图。

## 意图定义

### chat（闲聊/查询）
用户只是在聊天、问候、感谢，或者查询已有的信息（查进度、查分数、查个人信息）。
关键词：你好、谢谢、再见、在吗、晚安、我的进度、我的成绩、查一下、是什么
注意：如果用户想创建/生成新内容而不是查询已有信息，不要分类为chat。

### ppt（PPT制作）
用户想制作PPT、幻灯片、演示文稿、课件。
关键词：PPT、幻灯片、演示文稿、课件、做PPT、生成PPT、答辩PPT
例如："帮我做Java的PPT"、"生成数据结构的教学PPT"、"做一个关于AI的PPT"

### video（视频学习）
用户想找视频、看教程、上网课。
关键词：视频、b站、教程、网课、慕课、公开课、视频教学
例如："推荐Python视频"、"b站有什么好的算法教程"、"找数据结构网课"

### study_plan（学习规划）
用户想要制定学习计划、学习路线、学习安排。
关键词：学习计划、学习路线、规划、多久能学会、学习阶段、学习路径、从零开始、速通
例如："制定Rust学习计划"、"一个月学会前端"、"算法学习路线"

### practice（编程练习）
用户想写代码、做编程练习、实现算法。
关键词：编程题、写代码、练习题、算法实现、手撕、coding、写一个函数
例如："写一个快排"、"实现链表反转"、"来道算法题"

### question_gen（出题做题）
用户想要出题、做题、测验、考试。
关键词：选择题、出题、刷题、考考我、来几道题、笔试面试题
例如："出几道二叉树选择题"、"考考我排序算法"

### judge_code（代码判题/调试）
用户代码有问题需要检查、调试、找bug。
关键词：debug、报错、编译失败、代码不对、哪里错了、运行出错
例如："这段代码为什么报错"、"帮我debug"、"编译失败了"

### doc_gen（文档生成）
用户想写文档、笔记、总结、报告。
关键词：文档、笔记、总结、报告、整理笔记、写总结、归纳
例如："帮我写个学习总结"、"整理二叉树笔记"、"写一份报告"

### teacher_advice（学习建议）
用户在学习中遇到困难、需要建议、学习方法指导。
关键词：怎么学、学不会、看不懂、迷茫、学习方法、建议、求教、困惑
例如："学不会递归怎么办"、"怎么提高编程能力"、"学习方法"

### extension（拓展延伸）
用户想深入了解更多相关资料、进阶内容。
关键词：拓展、延伸阅读、进阶、深入理解、原理、源码、推荐书
例如："推荐几本算法书"、"深入理解操作系统"、"拓展阅读"

### mindmap（思维导图）
用户想生成思维导图、脑图、知识框架。
关键词：思维导图、脑图、导图、知识框架、概念图、知识图谱
例如："生成二叉树思维导图"、"画一个排序算法脑图"

### animation（动画/可视化）
用户想生成动画、可视化演示、动态HTML。
关键词：动画、可视化、动态演示、排序动画、过程动画
例如："生成排序算法动画"、"做链表反转的可视化"

### profile_modify（修改个人信息）
用户想修改自己的个人信息（姓名、专业、年级等）。
关键词：修改信息、改名字、改专业、完善资料、更新信息
例如："帮我改名字"、"修改年级"、"更新专业"

### register（用户注册）
用户想注册账号、登记信息。
关键词：注册、新用户、登记、创建账户
例如："我要注册"、"我是新用户"

### refine_ppt（PPT优化）
用户想优化已有的PPT大纲、结构、排版。
关键词：大纲、提炼、精简、润色、PPT优化、排版、逻辑梳理
例如："帮我提炼PPT大纲"、"优化这份PPT的结构"

### unrecognized（无意义输入）
输入没有实际含义，或是测试文本、乱码。
关键词：asdf、test、abc、123、随意、都行、无意义

## 重要规则

1. "帮我"、"请"、"我想"、"能不能"、"可以帮我"等只是礼貌用语，不改变核心意图。
   ✅ "帮我做PPT" → ppt（核心是做PPT）
   ✅ "帮我制定学习计划" → study_plan（核心是制定计划）
   ❌ 不要把"帮我做PPT"分类为chat
   
2. "帮我查一下"、"我的进度"、"我的成绩"、"我的信息" → chat（查询已有信息）

3. 有具体主题词（PPT/视频/代码/文档/导图/动画）时优先匹配对应意图

4. 如果用户同时提到多个意图，取最核心的那个

## 输出格式

只输出意图名称（小写英文），不要有任何其他内容。

用户输入：{text}"""

            response = llm.invoke(prompt)
            result = response.content.strip()

            intent = result
            if intent not in INTENT_EXAMPLES:
                for label in INTENT_EXAMPLES:
                    if label in result:
                        intent = label
                        break
                else:
                    intent = "unrecognized"

            return intent, 0.85
        except Exception as e:
            print(f"  ⚠️ LLM 回退调用失败: {e}")
            return None

    def _ensemble_with_llm(self, local_result: Tuple[str, float], 
                           llm_result: Optional[Tuple[str, float]],
                           text: str) -> Tuple[str, float]:
        """
        加权集成本地分类器和 LLM 结果。
        
        策略：
        - 本地置信度 >= 0.7: 完全信任本地结果
        - 本地置信度 < 0.3: 完全信任 LLM
        - 0.3 <= 本地置信度 < 0.7: 加权融合
        
        ★★★ chat保护：当本地模型判定为具体意图而LLM判定为chat时，
        要求LLM有更高权重才允许覆盖，避免"帮我"等礼貌用语误导LLM。 ★★★
        """
        if llm_result is None:
            return local_result
        
        local_intent, local_conf = local_result
        llm_intent, llm_conf = llm_result
        
        if local_conf >= 0.7:
            return local_result
        
        # ★★★ chat保护：本地模型低置信度但为具体意图时，不让LLM轻易覆盖为chat ★★★
        if local_conf < 0.3:
            if llm_intent == "chat" and local_intent not in ("chat", "unrecognized"):
                # LLM说是chat但模型有具体意图 → 降低LLM可信度，改用0.5权重
                print(f"  ⚠️ [LLM回退] 本地={local_intent}({local_conf:.2f}) vs LLM=chat，保守使用LLM结果")
                return llm_intent, 0.5
            print(f"  ⚠️ [LLM回退] 本地置信度低({local_conf:.2f})，使用LLM结果: {llm_intent}")
            return llm_result
        
        w_local = (local_conf - 0.3) / 0.4
        w_llm = 1.0 - w_local
        
        if local_intent == llm_intent:
            combined_conf = local_conf * w_local + llm_conf * w_llm
            return local_intent, combined_conf
        else:
            # ★★★ chat保护：LLM说chat但本地有具体意图，要求LLM权重够高才覆盖 ★★★
            if llm_intent == "chat" and local_intent not in ("chat", "unrecognized"):
                _override_threshold = 0.7  # LLM权重需超过0.7才允许chat覆盖
                if w_llm > _override_threshold:
                    print(f"  ⚠️ [LLM回退] 集成: 本地={local_intent}({local_conf:.2f}) → LLM={llm_intent}({llm_conf:.2f}) (LLM权重={w_llm:.2f} > {_override_threshold})")
                    return llm_intent, llm_conf * w_llm + local_conf * 0.1
                else:
                    print(f"  🛡️ [LLM-chat保护] 本地={local_intent}({local_conf:.2f})，LLM权重={w_llm:.2f}不足，保留本地结果")
                    return local_intent, local_conf
            # ★★★ 意图分歧时的证据加权：置信度比值决定胜负，无硬阈值 ★★★
            # llm_conf 已内化共识度：3/3=0.85, 2/3=0.73, 1/3=0.62
            # local_conf 来自 MLP/余弦相似度
            # 当一方证据占比 > 0.5 时胜出，置信度按证据占比混合
            else:
                total_evidence = local_conf + llm_conf
                llm_share = llm_conf / total_evidence
                if llm_share > 0.5:
                    blend = llm_conf * llm_share + local_conf * (1 - llm_share)
                    print(f"  ⚖️ [证据加权] 本地={local_intent}({local_conf:.2f}) < LLM={llm_intent}({llm_conf:.2f}) → {llm_intent}({blend:.2f})")
                    return llm_intent, blend
                else:
                    blend = local_conf * (1 - llm_share) + llm_conf * llm_share
                    print(f"  ⚖️ [证据加权] 本地={local_intent}({local_conf:.2f}) ≥ LLM={llm_intent}({llm_conf:.2f}) → {local_intent}({blend:.2f})")
                    return local_intent, blend

    # ==================== MLP 分类头：从磁盘加载 ====================

    def _load_mlp_model(self):
        """从磁盘加载已训练的 MLP 模型，不存在则提示用户训练"""
        if not _check_sklearn_available():
            print("  ℹ️  sklearn 未安装，跳过 MLP 模型加载")
            return
        model_path = os.path.join(_MLP_MODEL_DIR, "mlp.pkl")
        encoder_path = os.path.join(_MLP_MODEL_DIR, "label_encoder.pkl")
        if not (os.path.exists(model_path) and os.path.exists(encoder_path)):
            print(f"  ℹ️  MLP 模型未训练（运行 python train_intent_classifier.py 生成），使用余弦相似度")
            return
        try:
            with open(model_path, "rb") as f:
                self._mlp = pickle.load(f)
            with open(encoder_path, "rb") as f:
                self._label_encoder = pickle.load(f)
            print(f"  ✅ 已从磁盘加载 MLP 分类头（{len(self._label_encoder.classes_)} 类）")
        except Exception as e:
            print(f"  ⚠️ 加载 MLP 模型失败: {e}，降级为余弦相似度")

    # ==================== 主分类入口 ====================

    @staticmethod
    def _fix_common_typos(text: str) -> str:
        """
        纠正常见错别字。

        策略:
        1. 手工白名单：高置信度的固定错别字映射（长词优先）
        """
        # ── 阶段 1：手工白名单（高置信度，长词优先）──
        replacements = [
            # ===== 学习计划相关错别字 =====
            ("学习计画", "学习计划"),
            ("的计画", "的计划"),
            ("路线计画", "路线计划"),
            ("学习激化", "学习计划"),
            ("的激化", "的计划"),
            ("学习几乎", "学习计划"),
            ("的几乎", "的计划"),
            ("计画", "计划"),
            ("几乎", "计划"),
            ("激化", "计划"),
            ("帮我指定一", "帮我制定一"),
            ("指定学习计", "制定学习计"),
            ("指定一个", "制定一个"),
            ("指定关于", "制定关于"),
            ("指定学习路", "制定学习路"),
            ("指定学习规", "制定学习规"),
            ("指定学习安", "制定学习安"),
            # ===== 视频相关错别字 =====
            ("的时评", "的视频"),
            ("看时评", "看视频"),
            ("时评教程", "视频教程"),
            ("时评教学", "视频教学"),
            ("时评课程", "视频课程"),
            ("二叉时评", "二叉树视频"),
            ("的时评资", "的视频资"),
            # 单独替换"时评"（必须在长词之后）
            ("时评", "视频"),
        ]
        for wrong, correct in replacements:
            text = text.replace(wrong, correct)

        return text

    def classify(self, text: str, use_llm_fallback: bool = True) -> Tuple[str, float]:
        text_stripped = text.strip()
        if not text_stripped:
            return "chat", 0.0

        cache_key = f"{text_stripped}:{use_llm_fallback}"
        if cache_key in self._cache:
            self._cache.move_to_end(cache_key)
            return self._cache[cache_key]

        text_corrected = self._fix_common_typos(text_stripped)

        # ★★★ P0-1: 精确例句匹配快速路径（绕过模型）★★★
        # 训练集已知句子直接命中，避免 MLP 对训练样本的误判
        _norm_key = self._normalize_text(text_corrected)
        if _norm_key in self._exact_match_map:
            _exact_intent = self._exact_match_map[_norm_key]
            print(f"  ✅ [精确匹配] 命中训练例句 → {_exact_intent}(1.00)")
            result = (_exact_intent, 1.0)
            self._add_to_cache(cache_key, result[0], result[1])
            return result

        result = self._classify_with_model(text_corrected)

        # ========== 模型失败 → 直接交给大模型 ==========
        if result is None:
            result = ("chat", 0.3)
        else:
            # Query消歧：纯查询模式 → chat
            if result[0] != "chat":
                # 使用纠错后的文本做消歧
                result = self._disambiguate_query(text_corrected, result)

        # ========== 三级置信度门控（调整后阈值：0.75/0.45，减少不必要的 LLM 调用）==========
        if use_llm_fallback:
            if result[1] >= 0.75:
                print(f"  ✅ [直接采用] {result[0]}({result[1]:.2f}) ≥ 0.75")
            elif result[1] >= 0.45:
                llm_result = self._multi_agent_llm_fallback(text_stripped)
                if llm_result is None:
                    llm_result = self._llm_fallback(text_stripped)
                if llm_result:
                    result = self._ensemble_with_llm(result, llm_result, text_stripped)
            else:
                llm_result = self._llm_fallback(text_stripped)
                if llm_result:
                    print(f"  ⚠️ [低置信直通LLM] 本地={result[0]}({result[1]:.2f}) → LLM={llm_result[0]}({llm_result[1]:.2f})")
                    result = llm_result

        self._add_to_cache(cache_key, result[0], result[1])
        return result

    # ★★★ Query vs Execute 消歧：查询已有信息 → chat，创建/执行新内容保留原意图 ★★★
    _QUERY_PATTERNS = [
        "知道我的", "查看我的", "查询我的", "显示我的",
        "是什么", "有哪些", "有没有",
        "查一下", "我的进度", "我的分数", "我的成绩",
        "我的信息", "我的特征", "我的画像", "我的名字",
        "我的学习计划", "我的复习计划",
    ]
    _EXECUTE_PATTERNS = [
        "帮我", "生成", "写一", "写个", "写代", "练习", "出题",
        "实现", "调试", "检查", "修复", "制作", "创建", "制定",
        "debug", "改一下", "报错", "错误", "bug", "代码哪里",
    ]

    def _disambiguate_query(self, text: str, embed_result: Tuple[str, float]) -> Tuple[str, float]:
        """如果文本是查询已有信息（非创建新内容），返回 ('chat', conf)"""
        is_query = any(q in text for q in self._QUERY_PATTERNS)
        is_execute = any(e in text for e in self._EXECUTE_PATTERNS)
        if is_query and not is_execute:
            print(f"  ⚠️ [Query消歧] 原意图 {embed_result[0]}({embed_result[1]:.2f})，检测到纯查询模式，重路由到 chat")
            return ("chat", embed_result[1])
        return embed_result

    def _classify_with_model(self, text: str) -> Optional[Tuple[str, float]]:
        """MLP 优先，退化到余弦相似度兜底"""
        mlp_result = None
        if _HAS_SKLEARN and self._mlp is not None:
            mlp_result = self._classify_with_mlp(text)
            if mlp_result is not None and mlp_result[1] >= 0.45:
                # ★★★ 关键词消歧（不限置信度）：如果关键词匹配到专有词（如"编程题"→"practice"），
                # 覆盖 MLP 结果，避免 MLP 将"生成编程题"误判为 judge_code/question_gen ★★★
                kw_result = self._keyword_fallback(text)
                if kw_result and kw_result[0] != mlp_result[0]:
                    kw_intent = kw_result[0]
                    exclusive_kws = _EXCLUSIVE_KEYWORDS.get(kw_intent, [])
                    if any(kw in text.lower() for kw in exclusive_kws):
                        print(f"  ⚠️ [MLP关键词消歧] MLP={mlp_result[0]}({mlp_result[1]:.2f}) "
                              f"→ 关键词专有词覆盖为 {kw_intent}({kw_result[1]:.2f})")
                        return kw_result
                return mlp_result
        sim_result = self._classify_with_similarity(text)
        return sim_result

    def _classify_with_mlp(self, text: str) -> Optional[Tuple[str, float]]:
        """使用 MLP 分类头预测意图"""
        try:
            if self._model is None or self._mlp is None:
                return None
            vec = self._model.encode(text, normalize_embeddings=True).reshape(1, -1)
            probs = self._mlp.predict_proba(vec)[0]
            best_idx = int(np.argmax(probs))
            best_score = float(probs[best_idx])
            best_intent = str(self._label_encoder.inverse_transform([best_idx])[0])
            if best_score > 0.3:
                return best_intent, best_score
            return None
        except Exception as e:
            print(f"  MLP 分类失败: {type(e).__name__}: {e}")
            return None

    def _classify_with_mlp_top_k(self, text: str, k: int = 3) -> Optional[List[Tuple[str, float]]]:
        """使用 MLP 分类头返回 top-k 候选意图"""
        try:
            if self._model is None or self._mlp is None:
                return None
            vec = self._model.encode(text, normalize_embeddings=True).reshape(1, -1)
            probs = self._mlp.predict_proba(vec)[0]
            indices = np.argsort(probs)[::-1][:k]
            results = []
            for idx in indices:
                intent = str(self._label_encoder.inverse_transform([int(idx)])[0])
                score = float(probs[idx])
                if score > 0.1:
                    results.append((intent, score))
            return results if results else None
        except Exception as e:
            print(f"  MLP Top-K 分类失败: {type(e).__name__}: {e}")
            return None

    def _classify_with_similarity(self, text: str) -> Optional[Tuple[str, float]]:
        """余弦相似度兜底（原 _classify_with_embedding）"""
        try:
            if self._model is None:
                # ★★★ 模型未加载完 → 降级为关键词匹配，不阻塞等待 ★★★
                print("  ⚠️ [意图分类] 嵌入模型尚未加载完成，使用关键词匹配降级")
                return self._keyword_fallback(text)

            vec = self._model.encode(text, normalize_embeddings=True)

            best_intent = None
            best_score = -1.0

            for intent, intent_embs in self._intent_embeddings.items():
                sims = np.dot(intent_embs, vec)
                # ★★★ 取 top-5 相似度的均值：固定数量而非按比例，避免大意图的噪声例句拉低分数 ★★★
                top_k = min(5, max(1, len(sims)))
                avg_score = float(np.mean(sorted(sims, reverse=True)[:top_k]))
                if avg_score > best_score:
                    best_score = avg_score
                    best_intent = intent

            if best_intent and best_score > 0.3:
                return best_intent, best_score

            return None

        except Exception as e:
            print(f"  嵌入分类失败: {type(e).__name__}: {e}")
            return None

    def _classify_with_similarity_top_k(self, text: str, k: int = 3) -> Optional[List[Tuple[str, float]]]:
        """余弦相似度返回 top-k 候选意图"""
        try:
            if self._model is None:
                return None

            vec = self._model.encode(text, normalize_embeddings=True)

            scores = []
            for intent, intent_embs in self._intent_embeddings.items():
                sims = np.dot(intent_embs, vec)
                # ★★★ 统一使用 top-5（与 _classify_with_similarity 保持一致）★★★
                top_k_sim = min(5, max(1, len(sims)))
                avg_score = float(np.mean(sorted(sims, reverse=True)[:top_k_sim]))
                if avg_score > 0.1:
                    scores.append((intent, avg_score))

            scores.sort(key=lambda x: x[1], reverse=True)
            return scores[:k] if scores else None

        except Exception as e:
            print(f"  嵌入 Top-K 分类失败: {type(e).__name__}: {e}")
            return None

    def _keyword_fallback(self, text: str) -> Tuple[str, float]:
        text_lower = text.lower()
        all_intents = list(FALLBACK_KEYWORDS.keys())

        scores = {}
        for intent in all_intents:
            keywords = self._fallback_keywords.get(intent, [])
            score = sum(1 for kw in keywords if kw in text_lower)
            if score > 0:
                # ★★★ chat 意图排除宽泛关键词：避免"是什么""帮我"等通用词误升chat得分 ★★★
                if intent == "chat":
                    vague_count = sum(1 for kw in keywords if kw in _VAGUE_CHAT_KEYWORDS and kw in text_lower)
                    score = max(0, score - vague_count)
                if score > 0:
                    scores[intent] = score

        # study_plan 得分不做额外加权（移除 2.5x 偏袒，避免压制其他意图）

        if scores:
            max_score = max(scores.values())
            tied = [intent for intent, s in scores.items() if s == max_score]

            if len(tied) > 1:
                exact_matches = []
                for intent in tied:
                    examples = INTENT_EXAMPLES.get(intent, [])
                    if text in examples:
                        exact_matches.append(intent)
                if exact_matches:
                    best = exact_matches[0]
                else:
                    best = tied[0]
            else:
                best = tied[0]

            return best, min(0.3 + scores[best] * 0.15, 0.7)

        return "chat", 0.3

    def classify_with_details(self, text: str) -> dict:
        intent, confidence = self.classify(text)
        method = "embedding" if confidence > 0.5 else "keyword"
        return {"intent": intent, "confidence": confidence, "method": method}

    def _add_to_cache(self, text: str, intent: str, confidence: float):
        if len(self._cache) >= self._cache_size:
            self._cache.popitem(last=False)
        self._cache[text] = (intent, confidence)


# ==================== 全局单例 ====================

_classifier_instance = None
_classifier_loading_started = False  # ★★★ 防止重复启动加载线程 ★★★


def get_intent_classifier() -> IntentClassifier:
    global _classifier_instance, _classifier_loading_started
    if _classifier_instance is None:
        _classifier_instance = IntentClassifier()
    # ★★★ 首次调用同步加载模型（阻塞但保证后续调用不卡）★★★
    if _classifier_instance._model is None and not _classifier_loading_started:
        _classifier_loading_started = True
        print("  ⏳ 正在加载语义嵌入模型 BAAI/bge-base-zh-v1.5（首次加载约需10-30秒）...")
        _classifier_instance._load_model()
        print("  ✅ 语义嵌入模型加载完成")
    return _classifier_instance